mapper.update:
CREATE INDEX ${tableName}_IDX1 ON ${tableName} (METADATA_HASH_CODE, EXP_DATE DESC);
CREATE INDEX ${tableName}_IDX2 ON ${tableName} (IMG_STATUS, REQ_DATE);
CREATE INDEX ${tableName}_IDX3 ON ${tableName} (IMG_STATUS, EXP_DATE);

UPDATE ${tableName}
SET
    IMG_STATUS = #{parameter.imageStatus}
    , METADATA_HASH_CODE = #{parameter.metadataHashCode}
    , IMG_PATH = #{parameter.imagePath}
    , FILE_URL = #{parameter.fileUrl}
    , REG_DATE = TO_TIMESTAMP(#{parameter.registerDate}, 'YYYYMMDDHH24MISS')
    , EXP_DATE = TO_TIMESTAMP(#{parameter.expireDate}, 'YYYYMMDDHH24MISS')
    , DONE_DATE = TO_TIMESTAMP(#{parameter.doneDate}, 'YYYYMMDDHH24MISS')
    , DONE_CODE = #{parameter.doneCode}
    , DONE_CODE_DESC = #{parameter.doneCodeDescription}
WHERE
    IMG_KEY IS NULL
    IMG_KEY = #{parameter.key}
